#include <bits/stdc++.h>
using namespace std;

// Print the value category of an expression using decltype((e)).
template <class T> const char* cat() {
    if constexpr (is_lvalue_reference_v<T>) return "lvalue";
    else if constexpr (is_rvalue_reference_v<T>) return "xvalue";
    else return "prvalue";
}
struct S { int m = 1; };
S make() { return S{}; }
int main() {
    int x = 5;
    int a[3] = {1, 2, 3};
    // decltype((e)): T& for lvalue, T&& for xvalue, T for prvalue
    cout << "x            : " << cat<decltype((x))>() << "\n";
    cout << "a[1]         : " << cat<decltype((a[1]))>() << "\n";
    cout << "x + 1        : " << cat<decltype((x + 1))>() << "\n";
    cout << "42           : " << cat<decltype((42))>() << "\n";
    cout << "move(x)      : " << cat<decltype((std::move(x)))>() << "\n";
    cout << "make()       : " << cat<decltype((make()))>() << "\n";
    cout << "make().m     : " << cat<decltype((make().m))>() << "\n";
    cout << "\"hi\" literal : " << cat<decltype(("hi"))>() << "\n";
}

