using namespace std;

struct Tracer {
    string s;
    Tracer(string v) : s(std::move(v)) {}
    Tracer(const Tracer& o) : s(o.s) { cout << "  copy ctor\n"; }
    Tracer(Tracer&& o) noexcept : s(std::move(o.s)) { cout << "  move ctor\n"; }
};
int main() {
    Tracer a("hello world, a long enough string to live on the heap");
    cout << "move(a) alone:\n";
    auto&& r = std::move(a);          // only a cast: nothing printed, nothing moved
    cout << "  a.s size still " << a.s.size() << "\n";
    cout << "Tracer b(move(a)):\n";
    Tracer b(std::move(a));           // the move ctor does the real transfer
    cout << "  a.s size now " << a.s.size() << " (valid but unspecified)\n";
    const Tracer c("const object");
    cout << "Tracer d(move(c)) on const:\n";
    Tracer d(std::move(c));           // const rvalue cannot bind T&&, so copy runs
    (void)r;
}

#include <bits/stdc++.h>
using namespace std;

class Buf {
    int* p_; size_t n_;
public:
    explicit Buf(size_t n) : p_(new int[n]), n_(n) { for (size_t i = 0; i < n; i++) p_[i] = (int)i; }
    // Move ctor: steal the pointer, null the source so only one owner frees it
    Buf(Buf&& o) noexcept : p_(std::exchange(o.p_, nullptr)), n_(std::exchange(o.n_, 0)) {}
    Buf& operator=(Buf&& o) noexcept {
        if (this != &o) {             // guard against self-move
            delete[] p_;              // free our old resource to avoid a leak
            p_ = std::exchange(o.p_, nullptr);
            n_ = std::exchange(o.n_, 0);
        }
        return *this;
    }
    Buf(const Buf&) = delete;
    Buf& operator=(const Buf&) = delete;
    ~Buf() { delete[] p_; }
    size_t size() const { return n_; }
    bool empty() const { return p_ == nullptr; }
};
int main() {
    Buf a(4), b(2);
    Buf c(std::move(a));
    cout << "after move ctor: a.size=" << a.size() << " c.size=" << c.size() << "\n";
    b = std::move(c);
    cout << "after move assign: c.empty=" << c.empty() << " b.size=" << b.size() << "\n";
    b = std::move(b);                 // self-move must not destroy the data
    cout << "after self-move: b.size=" << b.size() << "\n";
    cout << "nothrow move ctor: " << is_nothrow_move_constructible_v<Buf> << "\n";
}

#include <bits/stdc++.h>
using namespace std;

// Rule of 5: declaring a destructor suppresses implicit moves -> copies.
struct Legacy {
    vector<int> v;
    ~Legacy() {}                       // user-declared destructor
};
// Rule of 0: no special members at all; compiler generates correct ones.
struct Modern {
    vector<int> v;
};
// Move-only: copy deleted, move defaulted.
struct MoveOnly {
    unique_ptr<int> p = make_unique<int>(7);
};
template <class T> void test(const char* name) {
    T a; a.v.assign(1000, 1);
    T b(std::move(a));
    cout << name << ": source size after 'move' = " << a.v.size()
         << (a.v.empty() ? " (moved)" : " (copied!)") << "\n";
}
int main() {
    test<Legacy>("Legacy (dtor declared)");
    test<Modern>("Modern (rule of 0)    ");
    cout << "MoveOnly copyable: " << is_copy_constructible_v<MoveOnly>
         << ", movable: " << is_move_constructible_v<MoveOnly> << "\n";
    cout << "Legacy nothrow move: " << is_nothrow_move_constructible_v<Legacy> << "\n";
    cout << "Modern nothrow move: " << is_nothrow_move_constructible_v<Modern> << "\n";
}

#include <bits/stdc++.h>
using namespace std;

static int copies = 0, moves = 0;
struct Safe {                         // noexcept move: vector will move
    Safe() {}
    Safe(const Safe&) { copies++; }
    Safe(Safe&&) noexcept { moves++; }
};
struct Risky {                        // move may throw: vector copies on growth
    Risky() {}
    Risky(const Risky&) { copies++; }
    Risky(Risky&&) { moves++; }
};
template <class T> void run(const char* name) {
    copies = moves = 0;
    vector<T> v;
    v.reserve(1);
    v.emplace_back();
    v.emplace_back();                 // growth: existing element is relocated
    cout << name << ": copies=" << copies << " moves=" << moves << "\n";
}
int main() {
    run<Safe>("noexcept move");
    run<Risky>("throwing move");
    static_assert(is_nothrow_move_constructible_v<Safe>);
    static_assert(!is_nothrow_move_constructible_v<Risky>);
    cout << "checks passed\n";
}

#include <bits/stdc++.h>
using namespace std;

struct Item {
    string tag;
    Item(const string& s) : tag("copied:" + s) {}
    Item(string&& s) : tag("moved:" + s) {}
};
// Forwarding reference + std::forward keeps lvalue/rvalue-ness
template <class T, class... Args>
unique_ptr<T> my_make_unique(Args&&... args) {
    return unique_ptr<T>(new T(std::forward<Args>(args)...));
}
// Without forward every argument becomes an lvalue
template <class T, class... Args>
unique_ptr<T> bad_make_unique(Args&&... args) {
    return unique_ptr<T>(new T(args...));
}
int main() {
    string s = "abc";
    auto p1 = my_make_unique<Item>(s);               // lvalue -> copy overload
    auto p2 = my_make_unique<Item>(string("xyz"));   // rvalue -> move overload
    auto p3 = bad_make_unique<Item>(string("xyz"));  // forward missing
    cout << "forward lvalue : " << p1->tag << "\n";
    cout << "forward rvalue : " << p2->tag << "\n";
    cout << "no forward     : " << p3->tag << "\n";
    auto up = my_make_unique<int>(42);               // works with move-only result
    cout << "make<int>(42)  : " << *up << "\n";
}

#include <bits/stdc++.h>
using namespace std;

void sink(const string&) { cout << "  sink got lvalue (copy)\n"; }
void sink(string&&)      { cout << "  sink got rvalue (move)\n"; }

// Correct: forward preserves the caller's category
template <class T> void good(T&& x) { sink(std::forward<T>(x)); }
// Bug: move steals from the caller's lvalues
template <class T> void bad(T&& x) { sink(std::move(x)); }

int main() {
    string s = "keep me";
    cout << "good(lvalue):\n"; good(s);
    cout << "good(rvalue):\n"; good(string("tmp"));
    cout << "bad(lvalue):\n";  bad(s);       // sink takes string&& -> may empty s
    string t = "steal me";
    string sunk = std::move(t);               // what a real consumer would do
    cout << "after a real move, t = '" << t << "' (size " << t.size() << ")\n";
}

#include <bits/stdc++.h>
using namespace std;

struct Counter {
    int n = 10;
    function<int()> byThis()  { return [this] { return n; }; }   // pointer to object
    function<int()> byCopy()  { return [*this] { return n; }; }  // copy of whole object
};
int main() {
    int x = 1;
    auto byVal = [x] { return x; };      // copy at creation
    auto byRef = [&x] { return x; };     // reference to x
    auto mut = [x]() mutable { return ++x; };  // modifies its own copy only
    x = 99;
    cout << "[x]   sees " << byVal() << " (copied when created)\n";
    cout << "[&x]  sees " << byRef() << " (live reference)\n";
    cout << "mutable: " << mut() << ", " << mut() << " (own copy keeps state), x=" << x << "\n";
    auto up = make_unique<int>(5);
    auto owner = [p = std::move(up)] { return *p; };  // init-capture moves it in
    cout << "init-capture: " << owner() << ", original null: " << (up == nullptr) << "\n";
    function<int()> t, c;
    {
        Counter k; t = k.byThis(); c = k.byCopy();
        k.n = 20;
        cout << "[*this] sees " << c() << ", [this] sees " << t() << " (object alive)\n";
    }
    cout << "[*this] after object died: " << c() << " (safe)\n";
}

#include <bits/stdc++.h>
using namespace std;

vector<function<void()>> loop;               // stands in for an event loop queue

struct Widget : enable_shared_from_this<Widget> {
    string name;
    explicit Widget(string n) : name(std::move(n)) {}
    void postWeak() {
        // weak_from_this: skip the work if the object is already gone
        loop.push_back([w = weak_from_this()] {
            if (auto self = w.lock()) cout << "  weak: " << self->name << " still alive, run\n";
            else cout << "  weak: widget destroyed, skipped safely\n";
        });
    }
    void postStrong() {
        // shared_from_this: keeps the object alive until the callback runs
        loop.push_back([self = shared_from_this()] {
            cout << "  strong: " << self->name << " kept alive, run\n";
        });
    }
    ~Widget() { cout << "  ~Widget(" << name << ")\n"; }
};
int main() {
    {
        auto w = make_shared<Widget>("A");
        w->postWeak();
    }                                          // A destroyed before callback runs
    {
        auto w = make_shared<Widget>("B");
        w->postStrong();
    }                                          // B survives, lambda owns it
    cout << "running loop:\n";
    for (auto& f : loop) f();
    loop.clear();                              // last owner released here
}

#include <bits/stdc++.h>
using namespace std;

template <class T> string kind() {
    string s = is_const_v<remove_reference_t<T>> ? "const " : "";
    s += is_same_v<remove_cvref_t<T>, int> ? "int" : "other";
    if (is_lvalue_reference_v<T>) s += "&";
    if (is_rvalue_reference_v<T>) s += "&&";
    return s;
}
int g = 3;
decltype(auto) byValue()  { int local = 1; return local; }    // int
decltype(auto) byRef()    { return (g); }                      // int& (parens!)
int main() {
    int x = 10;
    const int& cr = x;
    auto a = cr;                    // drops ref and const -> int
    auto& b = cr;                   // keeps const -> const int&
    auto&& c = x;                   // forwarding ref, lvalue -> int&
    auto&& d = 5;                   // rvalue -> int&&
    decltype(x) e = 1;              // declared type: int
    decltype((x)) f = x;            // expression is lvalue: int&
    decltype(auto) h = cr;          // keeps reference: const int&
    cout << "auto a       : " << kind<decltype(a)>() << "\n";
    cout << "auto& b      : " << kind<decltype(b)>() << "\n";
    cout << "auto&& c     : " << kind<decltype(c)>() << "\n";
    cout << "auto&& d     : " << kind<decltype(d)>() << "\n";
    cout << "decltype(x)  : " << kind<decltype(e)>() << "\n";
    cout << "decltype((x)): " << kind<decltype(f)>() << "\n";
    cout << "decltype(auto) from cr: " << kind<decltype(h)>() << "\n";
    cout << "byValue: " << kind<decltype(byValue())>() << ", byRef: " << kind<decltype(byRef())>() << "\n";
    auto il = {1, 2, 3};            // initializer_list<int>
    cout << "auto il = {1,2,3} size " << il.size() << "\n";
}

#include <bits/stdc++.h>
using namespace std;

struct Point { int x, y; };            // aggregate: binds to public members in order
struct Rgb {                           // tuple-like via get<I>
    int r = 1, g = 2, b = 3;
};
template <size_t I> int get(const Rgb& c) { return I == 0 ? c.r : I == 1 ? c.g : c.b; }
namespace std {
template <> struct tuple_size<Rgb> : integral_constant<size_t, 3> {};
template <size_t I> struct tuple_element<I, Rgb> { using type = int; };
}
int main() {
    int arr[2] = {7, 8};
    auto [a0, a1] = arr;                         // array: e[0], e[1]
    Point p{3, 4};
    auto [px, py] = p;                           // copy of p
    auto& [rx, ry] = p;                          // aliases p
    rx = 30;
    Rgb c;
    auto [r, g, b] = c;                          // uses tuple_size and get<I>
    cout << "array: " << a0 << " " << a1 << "\n";
    cout << "copy px=" << px << ", alias p.x=" << p.x << "\n";
    cout << "tuple-like: " << r << g << b << "\n";
    map<string, int> m{{"a", 1}};
    for (auto [k, v] : m) v = 100;               // v is a copy of each element
    cout << "map after copy loop: a=" << m["a"] << "\n";
    for (auto& [k, v] : m) v = 100;              // alias: really modifies
    cout << "map after ref loop : a=" << m["a"] << "\n";
}

#include <bits/stdc++.h>
using namespace std;

constexpr int square(int n) { return n * n; }          // compile time or run time
consteval int cube(int n) { return n * n * n; }        // must be compile time
constinit int counter = square(4);                     // constant-initialised, still mutable
constexpr int factorial(int n) { return n <= 1 ? 1 : n * factorial(n - 1); }
static_assert(factorial(5) == 120, "checked at build time");

int main() {
    const int runtimeConst = []{ int v; v = 7; return v; }();   // const, value from code
    int input = 6;
    int a = square(input);                // runtime call (input not constant)
    constexpr int b = square(5);          // compile time
    int arr[square(3)];                   // array bound needs a constant expression
    int c = cube(3);                      // always compile time
    counter += 1;                         // constinit variable is mutable
    cout << "const (runtime value): " << runtimeConst << "\n";
    cout << "square(runtime 6)  = " << a << "\n";
    cout << "constexpr square(5) = " << b << "\n";
    cout << "array size         = " << sizeof(arr) / sizeof(arr[0]) << "\n";
    cout << "consteval cube(3)  = " << c << "\n";
    cout << "constinit counter  = " << counter << "\n";
    cout << "factorial(5)       = " << factorial(5) << "\n";
    cout << "in constant eval? " << (is_constant_evaluated() ? "yes" : "no") << "\n";
}

#include <bits/stdc++.h>
